// swiftlint:disable file_length
import Foundation

/// Pre-graded puzzles, used when generation cannot find a puzzle of the requested level in time
/// (CODESPEC 2.2: no silent fallback) and as practice drills by technique (CODESPEC 13.5).
/// Generated offline with this app's generator and LogicalSolver, so no licence applies, by
/// docs/audit/bundled-generate.swift (seed 20261114): 120 per level, each inside its level's
/// targets. Then practice-only lines: every board of the earlier sets (seeds 20261101, 20261103,
/// 20261113), so no drill is lost.
/// Each line: level|initial grid|solution|score|techniques|steps per tier|opening singles[|drill].
enum BundledPuzzles { // swiftlint:disable:this type_body_length
    struct Entry: Equatable {
        let difficulty: Difficulty
        let initialGrid: String
        let solutionGrid: String
        let score: Int
        let techniques: [Technique]
        /// A drill only: may be outside the level's targets, never offered as a level puzzle.
        var isDrillOnly = false
        var stepsPerTier: [Int]?
        var openingSingles: Int?

        /// The full grade, as PuzzleGrader gives it for this board.
        var grade: PuzzleGrade {
            PuzzleGrade(hardestTier: techniques.map(\.tier).max() ?? .basic, score: score, techniques: techniques,
                        stepsPerTier: stepsPerTier, openingSingles: openingSingles)
        }
    }

    static let all: [Entry] = data.split(separator: "\n").compactMap { line in
        let fields = line.split(separator: "|", omittingEmptySubsequences: false).map(String.init)
        guard fields.count == 7 || fields.count == 8, let score = Int(fields[3]),
              let difficulty = Difficulty(rawValue: fields[0]) else { return nil }
        let techniques = fields[4].split(separator: ",").compactMap { Technique(rawValue: String($0)) }
        return Entry(difficulty: difficulty, initialGrid: fields[1], solutionGrid: fields[2], score: score,
                     techniques: techniques, isDrillOnly: fields.count == 8,
                     stepsPerTier: fields[5].split(separator: ",").compactMap { Int($0) }, openingSingles: Int(fields[6]))
    }

    static func puzzles(for difficulty: Difficulty) -> [Entry] {
        all.filter { $0.difficulty == difficulty && !$0.isDrillOnly }
    }

    /// Practice puzzles that need the given technique, easiest first.
    static func drills(for technique: Technique) -> [Entry] {
        all.filter { $0.techniques.contains(technique) }.sorted { $0.score < $1.score }
    }

